// Reads donations from the Donorbox API (https://github.com/donorbox/donorbox-api).
// Basic auth: the Donorbox login email as the username, the API key as the
// password. The API is a paid Donorbox add-on and the key is shown only once
// when it is created, so it has to be generated by whoever owns the account.

export interface DonorboxDonation {
  id: number
  campaign?: { id: number; name: string } | null
  donor?: { id?: number; name?: string | null; first_name?: string | null; last_name?: string | null; email?: string | null } | null
  amount: string | number
  converted_amount?: string | number | null
  amount_refunded?: string | number | null
  recurring?: boolean
  status?: string
  donation_type?: string
  donation_date: string
  anonymous_donation?: boolean
  comment?: string | null
  donating_company?: string | null
  processing_fee?: string | number | null
  designation?: string | null
}

export class DonorboxError extends Error {}

const MAX_PAGES = 200

export function donorboxConfigured(): boolean {
  return Boolean(process.env.DONORBOX_EMAIL?.trim() && process.env.DONORBOX_API_KEY?.trim())
}

/** Donations dated from `fromDay` to `toDay` inclusive (YYYY-MM-DD). */
export async function fetchDonations(fromDay: string, toDay: string): Promise<DonorboxDonation[]> {
  if (!donorboxConfigured()) throw new DonorboxError('Donorbox API credentials are not set (DONORBOX_EMAIL and DONORBOX_API_KEY).')
  const base = (process.env.DONORBOX_API_BASE || 'https://donorbox.org').replace(/\/+$/, '')
  const auth = `Basic ${Buffer.from(`${process.env.DONORBOX_EMAIL!.trim()}:${process.env.DONORBOX_API_KEY!.trim()}`).toString('base64')}`
  const seen = new Map<number, DonorboxDonation>()
  // Stops on an empty page rather than a short one: a server that caps
  // per_page below what was asked would otherwise look finished early. A page
  // that adds nothing new also stops it, in case paging is ignored.
  for (let page = 1; page <= MAX_PAGES; page++) {
    const params = new URLSearchParams({ date_from: fromDay, date_to: toDay, page: String(page), per_page: '100' })
    const response = await fetch(`${base}/api/v1/donations?${params}`, {
      headers: { Authorization: auth, Accept: 'application/json' },
      cache: 'no-store',
      signal: AbortSignal.timeout(20_000),
    })
    if (response.status === 401 || response.status === 403) {
      throw new DonorboxError('Donorbox rejected the API credentials. Check DONORBOX_EMAIL and DONORBOX_API_KEY, and that the API add-on is active.')
    }
    if (!response.ok) throw new DonorboxError(`Donorbox returned ${response.status}.`)
    const rows = (await response.json()) as DonorboxDonation[]
    if (!Array.isArray(rows) || rows.length === 0) return Array.from(seen.values())
    const before = seen.size
    for (const row of rows) seen.set(row.id, row)
    if (seen.size === before) return Array.from(seen.values())
  }
  throw new DonorboxError(`More than ${MAX_PAGES} pages of donations. Narrow the date range.`)
}
